CREATE TABLE instruments(id INTEGER PRIMARY KEY,ticker TEXT NOT NULL,exchange TEXT NOT NULL,country TEXT NOT NULL,UNIQUE(ticker,exchange,country));
CREATE TABLE sources(id INTEGER PRIMARY KEY,publisher TEXT,url TEXT UNIQUE,source_type TEXT,license_notes TEXT,retrieved_at TEXT);
CREATE TABLE prices(instrument_id INTEGER NOT NULL REFERENCES instruments(id),traded_on TEXT NOT NULL,open REAL,high REAL,low REAL,close REAL,volume REAL,adj_close REAL,available_at TEXT,provider_source_id INTEGER REFERENCES sources(id),PRIMARY KEY(instrument_id,traded_on));
CREATE TABLE financial_facts(id INTEGER PRIMARY KEY);
CREATE TABLE investment_schema_versions(version INTEGER PRIMARY KEY,applied_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE jq_instrument_snapshots(instrument_id INTEGER NOT NULL REFERENCES instruments(id),effective_on TEXT NOT NULL,name TEXT NOT NULL,sector TEXT,market TEXT,raw_json TEXT NOT NULL,sha256 TEXT NOT NULL,fetched_at TEXT NOT NULL,source_id INTEGER NOT NULL REFERENCES sources(id),PRIMARY KEY(instrument_id,effective_on,sha256));
CREATE TABLE jq_financial_disclosures(id INTEGER PRIMARY KEY,instrument_id INTEGER NOT NULL REFERENCES instruments(id),disclosure_number TEXT NOT NULL,disclosed_at TEXT NOT NULL,period_end TEXT,document_type TEXT,raw_json TEXT NOT NULL,sha256 TEXT NOT NULL,fetched_at TEXT NOT NULL,source_id INTEGER NOT NULL REFERENCES sources(id),UNIQUE(instrument_id,disclosure_number,sha256));
CREATE TABLE jq_price_revisions(id INTEGER PRIMARY KEY,instrument_id INTEGER NOT NULL REFERENCES instruments(id),traded_on TEXT NOT NULL,raw_json TEXT NOT NULL,sha256 TEXT NOT NULL,fetched_at TEXT NOT NULL,source_id INTEGER NOT NULL REFERENCES sources(id),UNIQUE(instrument_id,traded_on,sha256));
CREATE TABLE investment_sync_units(endpoint TEXT NOT NULL,day TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('complete','skipped','failed')),reason TEXT,rows_received INTEGER NOT NULL DEFAULT 0,rows_saved INTEGER NOT NULL DEFAULT 0,finished_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(endpoint,day));
CREATE TABLE investment_import_runs(id INTEGER PRIMARY KEY,endpoint TEXT NOT NULL,day TEXT NOT NULL,status TEXT NOT NULL,rows_received INTEGER NOT NULL DEFAULT 0,rows_saved INTEGER NOT NULL DEFAULT 0,reason TEXT,recorded_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE investment_jobs(id TEXT PRIMARY KEY,requested_by TEXT NOT NULL,start_date TEXT NOT NULL,end_date TEXT NOT NULL,status TEXT NOT NULL,result_json TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,finished_at TEXT);
CREATE TABLE investment_relationships(id INTEGER PRIMARY KEY,from_instrument_id INTEGER NOT NULL REFERENCES instruments(id),to_instrument_id INTEGER NOT NULL REFERENCES instruments(id),kind TEXT NOT NULL,source_id INTEGER NOT NULL REFERENCES sources(id),observed_on TEXT NOT NULL,details_json TEXT NOT NULL DEFAULT '{}',UNIQUE(from_instrument_id,to_instrument_id,kind,source_id,observed_on));
CREATE TABLE investment_events(id INTEGER PRIMARY KEY,instrument_id INTEGER REFERENCES instruments(id),occurred_at TEXT NOT NULL,kind TEXT NOT NULL,description TEXT NOT NULL,source_id INTEGER NOT NULL REFERENCES sources(id),UNIQUE(instrument_id,occurred_at,kind,source_id));
CREATE TABLE investment_event_impacts(event_id INTEGER NOT NULL REFERENCES investment_events(id),instrument_id INTEGER NOT NULL REFERENCES instruments(id),hypothesis TEXT NOT NULL,evidence_source_id INTEGER NOT NULL REFERENCES sources(id),PRIMARY KEY(event_id,instrument_id,evidence_source_id));
CREATE TABLE investment_indicators(instrument_id INTEGER NOT NULL REFERENCES instruments(id),traded_on TEXT NOT NULL,method TEXT NOT NULL,value REAL NOT NULL,computed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(instrument_id,traded_on,method));
CREATE UNIQUE INDEX ux_investment_prices ON prices(instrument_id,traded_on);
CREATE UNIQUE INDEX ux_investment_sources ON sources(url);
CREATE UNIQUE INDEX ux_investment_instruments ON instruments(ticker,exchange,country);
CREATE INDEX ix_jq_master ON jq_instrument_snapshots(instrument_id,effective_on DESC,fetched_at DESC);
CREATE INDEX ix_jq_financials ON jq_financial_disclosures(instrument_id,disclosed_at DESC);
CREATE INDEX ix_investment_prices ON prices(instrument_id,traded_on DESC);
CREATE INDEX ix_investment_runs ON investment_import_runs(recorded_at DESC);
INSERT OR IGNORE INTO investment_schema_versions(version) VALUES(1);
CREATE TABLE investment_sync_lease(id INTEGER PRIMARY KEY CHECK(id=1),token TEXT NOT NULL,expires_at INTEGER NOT NULL);
